type LabEvidenceCardProps = {
  className?: string;
  children?: React.ReactNode | null;
  question?: string;
  showSource?: boolean;
  state?: "Open";
};

function LabEvidenceCard({ className, children = null, question = "What evidence supports this answer?", showSource = true, state = "Open" }: LabEvidenceCardProps) {
  return (
    <div className={className || "bg-[var(--lab-surface,#f7f7fc)] content-stretch flex flex-col gap-[var(--lab-gap,12px)] items-start p-[var(--lab-padding,24px)] relative rounded-[var(--lab-radius,16px)] w-[360px]"} data-node-id="57:16">
      <p className="[word-break:break-word] font-['Inter:Regular'] font-normal leading-[1.5] not-italic relative shrink-0 text-[16px] text-[color:var(--lab-accent,#2448ff)] w-full" data-node-id="57:17">
        Open
      </p>
      <p className="[word-break:break-word] font-['Inter:Regular'] font-normal leading-[1.5] not-italic relative shrink-0 text-[16px] text-[color:var(--lab-text,#11142b)] w-full" data-node-id="57:18">
        {question}
      </p>
      <p className="[word-break:break-word] font-['Inter:Regular'] font-normal leading-[1.5] not-italic relative shrink-0 text-[16px] text-[color:var(--lab-text,#11142b)] w-full" data-node-id="57:19">
        Review the source before making a visibility claim.
      </p>
      {showSource && (
        <p className="[word-break:break-word] font-['Inter:Regular'] font-normal leading-[1.5] not-italic relative shrink-0 text-[16px] text-[color:var(--lab-accent,#2448ff)] w-full" data-node-id="57:20">
          Source [1] available
        </p>
      )}
      <div className="content-stretch flex flex-col gap-[var(--lab-gap,12px)] items-start overflow-clip relative shrink-0 w-full" data-node-id="57:21" data-name="Source list">
        {children || (
          <p className="[word-break:break-word] font-['Inter:Regular'] font-normal leading-[1.5] not-italic relative shrink-0 text-[16px] text-[color:var(--lab-text,#11142b)] w-full" data-node-id="57:22">
            [1] Example source — inspect the original.
          </p>
        )}
      </div>
    </div>
  );
}
